"use strict";

const assert = require("node:assert/strict");
const fs = require("node:fs");
const { chromium } = require("playwright");

const BASE_URL = (process.env.BASE_URL || "http://127.0.0.1:4174").replace(/\/+$/, "");
const VIEWPORTS = [
  { name: "phone-320x568", width: 320, height: 568 },
  { name: "android-360x800", width: 360, height: 800 },
  { name: "desktop-1366x768", width: 1366, height: 768 }
];

// Every published calculator route, including the homepage Standard Calculator
// and every Urdu calculator page currently generated by the site.
const ROUTES = [
  { name: "home-standard", path: "/", root: ".ca-home-calculator", action: ".ca-home-calculator #calc-pad button[data-key='=']" },
  { name: "zakat-en", path: "/zakat-calculator/", root: "#tool-calculator", action: "#zakat-form button[type='submit']" },
  { name: "bmi-en", path: "/bmi-calculator/", root: "#tool-calculator", action: "#bmi-form button[type='submit']" },
  { name: "profit-loss-en", path: "/profit-loss-calculator/", root: "#tool-calculator", action: "#pl-form button[type='submit']" },
  { name: "discount-en", path: "/discount-calculator/", root: "#tool-calculator", action: "#disc-form button[type='submit']" },
  { name: "age-en", path: "/age-calculator/", root: "#tool-calculator", action: "#age-form button[type='submit']" },
  { name: "unit-converter-en", path: "/unit-converter/", root: "#tool-calculator", action: "#conv-form button[type='submit']" },
  { name: "standard-en", path: "/standard-calculator/", root: "#tool-calculator", action: "#calc-pad button[data-key='=']" },
  { name: "tasbih-en", path: "/tasbih-counter/", root: "#tool-calculator", action: "#t-tap" },
  { name: "stopwatch-en", path: "/stopwatch/", root: "#tool-calculator", action: "#sw-start" },
  { name: "years-to-days-en", path: "/years-to-days-calculator/", root: "#tool-calculator", action: "#yd-submit" },
  { name: "query-en", path: "/query-calculator/", root: "#tool-calculator", action: "#query-time-form button[type='submit']" },
  { name: "calorie-en", path: "/calorie-calculator/", root: "#calorie-form", action: "#cal-calculate" },
  { name: "emi-en", path: "/emi-calculator/", root: "#calculator", action: "#loan-form button[type='submit']" },
  { name: "percentage-en", path: "/percentage-calculator/", root: "#extra-calculator-form", action: "#extra-calculator-form button[type='submit']" },
  { name: "percentage-difference-en", path: "/percentage-difference-calculator/", root: "#extra-calculator-form", action: "#extra-calculator-form button[type='submit']" },
  { name: "ratio-en", path: "/ratio-calculator/", root: "#extra-calculator-form", action: "#extra-calculator-form button[type='submit']" },
  { name: "fraction-en", path: "/fraction-calculator/", root: "#extra-calculator-form", action: "#extra-calculator-form button[type='submit']" },
  { name: "compound-interest-en", path: "/compound-interest-calculator/", root: "#extra-calculator-form", action: "#extra-calculator-form button[type='submit']" },
  { name: "date-en", path: "/date-calculator/", root: "#extra-calculator-form", action: "#extra-calculator-form button[type='submit']" },
  { name: "zakat-ur", path: "/ur/zakat-calculator/", root: "#tool-calculator", action: "#zakat-form button[type='submit']" },
  { name: "profit-loss-ur", path: "/ur/profit-loss-calculator/", root: "#tool-calculator", action: "#pl-form button[type='submit']" },
  { name: "discount-ur", path: "/ur/discount-calculator/", root: "#tool-calculator", action: "#disc-form button[type='submit']" },
  { name: "age-ur", path: "/ur/age-calculator/", root: "#tool-calculator", action: "#age-form button[type='submit']" },
  { name: "unit-converter-ur", path: "/ur/unit-converter/", root: "#tool-calculator", action: "#conv-form button[type='submit']" },
  { name: "standard-ur", path: "/ur/standard-calculator/", root: "#tool-calculator", action: "#calc-pad button[data-key='=']" },
  { name: "tasbih-ur", path: "/ur/tasbih-counter/", root: "#tool-calculator", action: "#t-tap" },
  { name: "stopwatch-ur", path: "/ur/stopwatch/", root: "#tool-calculator", action: "#sw-start" }
];

function rect(element) {
  if (!element) return null;
  const r = element.getBoundingClientRect();
  const style = getComputedStyle(element);
  return {
    x: Math.round(r.x * 10) / 10,
    y: Math.round(r.y * 10) / 10,
    right: Math.round(r.right * 10) / 10,
    bottom: Math.round(r.bottom * 10) / 10,
    width: Math.round(r.width * 10) / 10,
    height: Math.round(r.height * 10) / 10,
    display: style.display,
    visibility: style.visibility
  };
}

(async () => {
  const browser = await chromium.launch({ headless: true, args: ["--no-sandbox"] });
  const failures = [];
  let scenarios = 0;
  const screenshotCount = 0;
  try {
    for (const route of ROUTES) {
      for (const viewport of VIEWPORTS) {
        const page = await browser.newPage({ viewport: { width: viewport.width, height: viewport.height }, deviceScaleFactor: 1 });
        const pageErrors = [];
        page.on("pageerror", error => pageErrors.push(error.message));
        const targetUrl = BASE_URL + route.path;
        let response;
        try {
          response = await page.goto(targetUrl, { waitUntil: "networkidle", timeout: 30000 });
          await page.evaluate(() => document.fonts && document.fonts.ready);
          const metrics = await page.evaluate(({ rootSelector, actionSelector }) => {
            const root = document.querySelector(rootSelector);
            const action = document.querySelector(actionSelector);
            const heading = document.querySelector("h1");
            const firstControl = root && root.querySelector("input:not([type='hidden']), select, textarea, button");
            const box = element => {
              if (!element) return null;
              const r = element.getBoundingClientRect();
              const style = getComputedStyle(element);
              return {
                x: Math.round(r.x * 10) / 10,
                y: Math.round(r.y * 10) / 10,
                right: Math.round(r.right * 10) / 10,
                bottom: Math.round(r.bottom * 10) / 10,
                width: Math.round(r.width * 10) / 10,
                height: Math.round(r.height * 10) / 10,
                display: style.display,
                visibility: style.visibility
              };
            };
            const rootRect = root && root.getBoundingClientRect();
            const actionRect = action && action.getBoundingClientRect();
            const firstRect = firstControl && firstControl.getBoundingClientRect();
            const visible = element => {
              if (!element) return false;
              const r = element.getBoundingClientRect();
              const s = getComputedStyle(element);
              return r.width > 0 && r.height > 0 && s.display !== "none" && s.visibility !== "hidden" && Number(s.opacity) > 0;
            };
            const actionVisible = visible(action);
            const actionInViewport = actionVisible && actionRect.top >= -1 && actionRect.bottom <= innerHeight - 2;
            const firstControlInViewport = visible(firstControl) && firstRect.top >= -1 && firstRect.bottom <= innerHeight - 1;
            const hitTarget = actionVisible
              ? document.elementFromPoint(actionRect.left + actionRect.width / 2, actionRect.top + actionRect.height / 2)
              : null;
            const actionReachable = !!action && !!hitTarget && (action === hitTarget || action.contains(hitTarget));
            return {
              viewport: { width: innerWidth, height: innerHeight },
              documentWidth: document.documentElement.scrollWidth,
              horizontalOverflow: document.documentElement.scrollWidth > innerWidth + 1,
              title: document.title,
              heading: heading ? heading.textContent.trim() : null,
              headingRect: box(heading),
              rootFound: !!root,
              rootRect: box(root),
              rootTopInViewport: !!rootRect && rootRect.top >= -1 && rootRect.top < innerHeight,
              rootFitsWidth: !!rootRect && rootRect.left >= -1 && rootRect.right <= innerWidth + 1,
              firstControlFound: !!firstControl,
              firstControlRect: box(firstControl),
              firstControlInViewport,
              actionFound: !!action,
              actionText: action ? action.textContent.trim() : null,
              actionRect: box(action),
              actionInViewport,
              actionReachable
            };
          }, { rootSelector: route.root, actionSelector: route.action });

          const status = response ? response.status() : 0;
          const screenshotPath = "/tmp/calculator-layout-" + route.name + "-" + viewport.name + ".png";
          await page.screenshot({ path: screenshotPath, fullPage: false });
          scenarios += 1;
          console.log("CALCULATOR_LAYOUT " + route.name + " " + viewport.name + " HTTP=" + status + " " + JSON.stringify(metrics) + " pageErrors=" + JSON.stringify(pageErrors));

          if (status !== 200) failures.push({ route: route.path, viewport: viewport.name, issue: "HTTP status " + status });
          if (!metrics.heading) failures.push({ route: route.path, viewport: viewport.name, issue: "Missing H1" });
          if (!metrics.rootFound) failures.push({ route: route.path, viewport: viewport.name, issue: "Missing calculator container " + route.root });
          if (!metrics.actionFound) failures.push({ route: route.path, viewport: viewport.name, issue: "Missing primary calculator action " + route.action });
          if (metrics.rootFound && !metrics.rootTopInViewport) failures.push({ route: route.path, viewport: viewport.name, issue: "Calculator container starts below the initial viewport", metrics });
          if (metrics.rootFound && !metrics.rootFitsWidth) failures.push({ route: route.path, viewport: viewport.name, issue: "Calculator container exceeds viewport width", metrics });
          if (metrics.actionFound && !metrics.actionInViewport) failures.push({ route: route.path, viewport: viewport.name, issue: "Primary calculator action is not fully visible without scrolling", metrics });
          if (metrics.actionFound && !metrics.actionReachable) failures.push({ route: route.path, viewport: viewport.name, issue: "Primary calculator action is obscured or not hit-testable", metrics });
          if (metrics.rootFound && !metrics.firstControlFound) failures.push({ route: route.path, viewport: viewport.name, issue: "No interactive calculator control found", metrics });
          if (metrics.firstControlFound && !metrics.firstControlInViewport) failures.push({ route: route.path, viewport: viewport.name, issue: "First calculator control is not visible without scrolling", metrics });
          if (metrics.horizontalOverflow) failures.push({ route: route.path, viewport: viewport.name, issue: "Horizontal page overflow", metrics });
          if (pageErrors.length) failures.push({ route: route.path, viewport: viewport.name, issue: "Browser page errors", errors: pageErrors });
        } catch (error) {
          failures.push({ route: route.path, viewport: viewport.name, issue: "Browser navigation or inspection failed", error: error.message });
          console.log("CALCULATOR_LAYOUT_ERROR " + route.name + " " + viewport.name + " " + error.message);
        } finally {
          await page.close();
        }
      }
    }
  } finally {
    await browser.close();
  }

  console.log("CALCULATOR_LAYOUT_TOTAL routes=" + ROUTES.length + " viewports=" + VIEWPORTS.length + " scenarios=" + scenarios + " screenshots=" + scenarios + " failures=" + failures.length);
  if (failures.length) {
    console.error("CALCULATOR_LAYOUT_FAILURES " + JSON.stringify(failures, null, 2));
    assert.fail(failures.length + " first-screen calculator layout failure(s) across " + scenarios + " scenarios");
  }
  console.log("PASS: all " + ROUTES.length + " English/Urdu calculator routes passed first-screen layout checks across " + VIEWPORTS.length + " viewports (" + scenarios + " browser scenarios).");
})().catch(error => {
  console.error(error);
  process.exitCode = 1;
});
